 * Recurring-issue rules. Reads are filtered by `orgId` except the job's
 * cross-tenant sweep.
 */
import { and, asc, count, eq } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, recurringIssues } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import type { RecurringIssueRow } from "@/server/db/schema/recurring-issues";
import type { OrgId, ProjectId, UserId } from "@/types/common";
import type { IssuePriority } from "@/types/issue";
import type { RecurringIssue } from "@/types/recurring-issue";

function toRule(row: RecurringIssueRow): RecurringIssue {
  return {
    id: row.id,
    orgId: row.orgId as OrgId,
    projectId: row.projectId as ProjectId,
    title: row.title,
    priority: row.priority as IssuePriority,
    assigneeId: row.assigneeId as UserId | null,
    cadence: row.cadence,
    weekday: row.weekday,
    timezone: row.timezone,
    startsOn: row.startsOn,
    lastOccurrenceOn: row.lastOccurrenceOn,
    paused: row.paused,
    createdBy: row.createdBy as UserId,
    createdAt: toIsoTimestamp(row.createdAt),
    updatedAt: toIsoTimestamp(row.updatedAt),
  };
}

export async function insertRule(input: {
  orgId: OrgId;
  projectId: ProjectId;
  title: string;
  priority: IssuePriority;
  assigneeId: UserId | null;
  cadence: "daily" | "weekly";
  weekday: number | null;
  timezone: string;
  startsOn: string;
  createdBy: UserId;
}): Promise<RecurringIssue> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(recurringIssues)
    .values({
      id: newId(),
      ...input,
      lastOccurrenceOn: null,
      paused: false,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();
  return toRule(row);
}

export async function findRule(
  orgId: OrgId,
  id: string,
): Promise<RecurringIssue | null> {
  const row = getDb()
    .select()
    .from(recurringIssues)
    .where(and(orgPredicate(recurringIssues.orgId, orgId), eq(recurringIssues.id, id)))
    .get();
  return row ? toRule(row) : null;
}

export async function listRules(orgId: OrgId): Promise<readonly RecurringIssue[]> {
  return getDb()
    .select()
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .orderBy(asc(recurringIssues.createdAt), asc(recurringIssues.rowid))
    .all()
    .map(toRule);
}

export async function countRules(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .get();
  return row?.value ?? 0;
}

/** Every non-paused rule of every organization, for the job. */
export async function listActiveRules(): Promise<readonly RecurringIssue[]> {
  return getDb()
    .select()
    .from(recurringIssues)
    .where(eq(recurringIssues.paused, false))
    .orderBy(asc(recurringIssues.createdAt))
    .all()
    .map(toRule);
}

export async function setPaused(
  orgId: OrgId,
  id: string,
  paused: boolean,
): Promise<RecurringIssue | null> {
  const row = getDb()
    .update(recurringIssues)
    .set({ paused, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(recurringIssues.orgId, orgId), eq(recurringIssues.id, id)))
    .returning()
    .get();
  return row ? toRule(row) : null;
}

export async function setLastOccurrence(
  orgId: OrgId,
  id: string,
  day: string,
): Promise<void> {
  getDb()
    .update(recurringIssues)
    .set({ lastOccurrenceOn: day, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(recurringIssues.orgId, orgId), eq(recurringIssues.id, id)))
    .run();
}
