import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { OrgId, UserId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";

const logger = createLogger("recurring-issue-job");

const MS_PER_DAY = 24 * 60 * 60 * 1000;

function localDate(now: Date, timeZone: string): string {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hourCycle: "h23",
  }).formatToParts(now);
  const get = (type: string) => parts.find((p) => p.type === type)?.value ?? "";
  return `${get("year").padStart(4, "0")}-${get("month")}-${get("day")}`;
}

function toUtcMs(day: string): number {
  const [y, m, d] = day.split("-").map(Number) as [number, number, number];
  return Date.UTC(y, m - 1, d);
}

function isoWeekday(day: string): number {
  const w = new Date(toUtcMs(day)).getUTCDay();
  return w === 0 ? 7 : w;
}

function shiftDays(day: string, delta: number): string {
  return new Date(toUtcMs(day) + delta * MS_PER_DAY).toISOString().slice(0, 10);
}

/** The latest occurrence that has started by `now`, or null. */
export function latestOccurrence(rule: RecurringIssue, now: Date): string | null {
  const today = localDate(now, rule.timezone);
  if (today < rule.startsOn) return null;

  if (rule.cadence === "daily") return today;
  if (rule.weekday === null) return null;

  const back = (isoWeekday(today) - rule.weekday + 7) % 7;
  const candidate = shiftDays(today, -back);
  return candidate >= rule.startsOn ? candidate : null;
}

export async function runRecurringIssueJob(now: Date): Promise<JobResult> {
  return runJob("recurring-issues", async (result) => {
    const rules = await ruleRepo.listActiveRules();

    for (const rule of rules) {
      try {
        if (await processRule(rule, now)) result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("recurring issue failed", {
          ruleId: rule.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

async function processRule(rule: RecurringIssue, now: Date): Promise<boolean> {
  const latest = latestOccurrence(rule, now);
  if (latest === null) return false;
  if (rule.lastOccurrenceOn !== null && latest <= rule.lastOccurrenceOn) {
    return false;
  }

  const project = await projectRepo.findProjectById(rule.orgId, rule.projectId);
  if (project === null || isArchived(project)) return false;

  const creator = await memberRepo.findMember(rule.orgId, rule.createdBy);
  const actor: Actor | null =
    creator !== null && creator.status === "active"
      ? { userId: rule.createdBy, orgId: rule.orgId, role: creator.role }
      : null;

  if (actor === null || !can(actor, "issue:create", projectResource(project))) {
    await ruleRepo.setPaused(rule.orgId, rule.id, true);
    return false;
  }

  const assigneeId = await activeAssignee(rule.orgId, rule.assigneeId);

  await createIssue(actor, {
    orgId: rule.orgId,
    projectId: rule.projectId,
    title: `${rule.title} (${latest})`,
    description: null,
    status: "backlog",
    priority: rule.priority,
    assigneeId,
    parentId: null,
    estimate: null,
    dueAt: null,
    labelIds: [],
  });

  await ruleRepo.setLastOccurrence(rule.orgId, rule.id, latest);
  return true;
}

async function activeAssignee(
  orgId: OrgId,
  assigneeId: UserId | null,
): Promise<UserId | null> {
  if (assigneeId === null) return null;
  const member = await memberRepo.findMember(orgId, assigneeId);
  return member !== null && member.status === "active" ? assigneeId : null;
}
